{"code": "import urllib.request
import json

tickers = ['SPYM', 'SCHG', 'DYNF', 'CGGR', 'SPHQ', 'XLG', 'AIQ', 'SOXQ', 'PSI']
results = {}

for ticker in tickers:
    try:
        url = f"https://query2.finance.yahoo.com/v8/finance/chart/{ticker}?interval=1d&range=1d"
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read())
            meta = data['chart']['result'][0]['meta']
            price = meta['regularMarketPrice']
            prev = meta['chartPreviousClose']
            change = round(price - prev, 2)
            pct = round(change / prev * 100, 2)
            results[ticker] = {'price': price, 'change': change, 'pct': pct}
    except Exception as e:
        results[ticker] = {'error': str(e)}

for ticker, data in results.items():
    if 'error' in data:
        print(f"{ticker}: ERROR - {data['error']}")
    else:
        sign = "+" if data['change'] >= 0 else ""
        print(f"{ticker}: ${data['price']} ({sign}{data['change']} / {sign}{data['pct']}%)")"}
